{
    static readonly JsonSerializerOptions Fields=new(){IncludeFields=true};
    static byte[] Bytes(string hex)=>Convert.FromHexString(hex);
    static OwnViewLifeSnapshot Stream(string[] sections)
    {var log=new OwnViewLifeLog();for(int i=0;i<sections.Length;i++){var b=Bytes(sections[i]);log.Observe(false,b,i,WireFormat.FindCreations(b));}return log.Snapshot();}
    static int Audit(string[] sections)
    {
        var kinds=new Dictionary<ushort,ushort>();int total=0;
        for(int i=0;i<sections.Length;i++)
        {
            var b=Bytes(sections[i]);var births=WireFormat.FindCreationEvents(b);int at=0;
            while(at<b.Length)
            {
                var birth=births.FirstOrDefault(c=>c.Offset==at);
                if(birth!=null){kinds[birth.Creation.ViewId]=birth.Creation.Goid;at+=birth.Length;total++;continue;}
                ushort? goid=at+2<=b.Length&&kinds.TryGetValue(BitConverter.ToUInt16(b,at),out var g)?g:null;
                Assert.True(MervAfterCombatFrames.TryRead(b,at,goid,out var frame),$"section{i} offset{at}: {Convert.ToHexString(b.AsSpan(at))}");
                var literal=b.AsSpan(at,frame.Length).ToArray();
                for(int cut=0;cut<literal.Length;cut++)
                    Assert.False(MervAfterCombatFrames.TryRead(literal[..cut],0,goid,out _),$"section{i} offset{at} truncated at{cut}");
                if(frame.Type==MervAfterCombatFrames.Kind.Delete)kinds.Remove(frame.View);
                at+=frame.Length;total++;
            }
            Assert.Equal(b.Length,at);
        }
        return total;
    }
