        {Assert.True(MervAfterCombatFrames.TryRead(b,at,goid,out var f));frames.Add(f);at+=f.Length;}
        Assert.Equal(new[]{11,14,43,9,47},frames.Select(f=>f.Length));Assert.Equal(124,at);
        Assert.Equal((ushort)29,BitConverter.ToUInt16(b,35));Assert.Equal((ushort)27,BitConverter.ToUInt16(b,37));
        Assert.DoesNotContain(frames,f=>f.View==27);
        var state=StateAgent105();var scope=MervAfterCurrentNpc.Capture(state,6);
        var before=MervAfterCurrentNpc.Require(Stream(Agent105.Take(87).ToArray()),scope,state);
        var after=MervAfterCurrentNpc.Require(Stream(Agent105.Take(88).ToArray()),scope,state);
        Assert.Equal(before.Position,after.Position);Assert.Equal(before.PositionSection,after.PositionSection);
        foreach(var npc in new ushort[]{7,8})
        {
            // Their latest authoritative states are dead; full framed deaths must agree, no alive-birth fallback.
            var all=StateAllAgents();var one=all.Mobs.Single(m=>m.Npc==npc);all.Mobs=new(){one};
            Assert.True(one.Dead);var dead=MervAfterCurrentNpc.Require(Stream(Agent105),MervAfterCurrentNpc.Capture(all,npc),all);
            Assert.NotEqual(27,dead.View.ViewId);
        }
    }
    [Fact]public void EveryTypedFrameCutoffMalformedAndWrongActorRefusesWithoutResynchronization()
    {
        var burst=Bytes(Agent105[87]);int at=0;
        foreach(var g in new ushort[]{12,599,12,599,599})
        {
            Assert.True(MervAfterCombatFrames.TryRead(burst,at,g,out var f));var raw=burst.AsSpan(at,f.Length).ToArray();
            for(int cut=0;cut<raw.Length;cut++)Assert.False(MervAfterCombatFrames.TryRead(raw[..cut],0,g,out _));
            Assert.False(MervAfterCombatFrames.TryRead(raw,0,g==599?(ushort)12:(ushort)599,out _));
            var malformed=(byte[])raw.Clone();malformed[2]=0xff;
            Assert.False(MervAfterCombatFrames.TryRead(malformed,0,g,out _));
            Assert.False(MervAfterCombatFrames.TryRead(new byte[]{99,88}.Concat(raw).ToArray(),0,g,out _));
            at+=f.Length;
        }
        var death=burst[77..];death[5]=5;Assert.False(MervAfterCombatFrames.TryRead(death,0,599,out _));
        death=burst[77..];death[^1]=1;Assert.False(MervAfterCombatFrames.TryRead(death,0,599,out _));
        var state=StateAgent105();var scope=MervAfterCurrentNpc.Capture(state,6);
        var unknown=new[]{Convert.ToHexString(new byte[]{99,88}.Concat(burst).ToArray())};
        Assert.Throws<InvalidDataException>(()=>MervAfterCurrentNpc.Require(Stream(Agent105.Take(87).Concat(unknown).ToArray()),scope,state));
        Assert.Throws<InvalidDataException>(()=>MervAfterCurrentNpc.Require(Stream(Agent105.Concat(new[]{"01000101001B00"}).ToArray()),scope,state));
    }
    [Fact]public void PrimarySubsequentMissNpcShotAndHealthEffectPreserveActorRoles()
    {
        foreach(bool first in new[]{false,true})foreach(bool hit in new[]{false,true})
        {
            var shot=ServerPackets.BuildRangedShot(27,((uint)27<<16)|29,1,2,3,4,5,first,hit);
            Assert.True(MervAfterCombatFrames.TryRead(shot,0,12,out var f));Assert.Equal(first?43:33,f.Length);
            Assert.Equal(MervAfterCombatFrames.Kind.Attribute,f.Type);Assert.Equal(-1,f.PositionOffset);
        }
        var npc=new byte[]{29,0}.Concat(ServerPackets.BuildNpcRangedShot(27,0x38,true,((uint)27<<16)|2,1,2,3)).ToArray();
        Assert.True(MervAfterCombatFrames.TryRead(npc,0,599,out var nf));Assert.Equal(29,nf.View);Assert.Equal(15,nf.PositionOffset);
        var health=new byte[]{29,0}.Concat(Mob.BuildHitUpdate(1,0x28000001,27)).ToArray();
        Assert.True(MervAfterCombatFrames.TryRead(health,0,599,out var hf));Assert.Equal(16,hf.Length);
        var death=new byte[]{29,0}.Concat(ServerPackets.BuildNpcDeathUpdate()).ToArray();
        Assert.True(MervAfterCombatFrames.TryRead(death,0,599,out var df));Assert.Equal(24,df.Length);Assert.Equal(-1,df.PositionOffset);
    }
